#include <algorithm>
#include <iostream>
#include <vector>

int main() {
    int n = 0;
    if (!(std::cin >> n)) return 1;
    if (n < 1 || n > 1000) return 1;
    std::vector<int> values;
    for (int i = 0; i < n; i++) {
        int value = 0;
        if (!(std::cin >> value)) return 1;
        if (value < -10000 || value > 10000) return 1;
        values.push_back(value);
    }
    int x = 0;
    if (!(std::cin >> x)) return 1;
    if (x < -10000 || x > 10000) return 1;
    auto position = std::find(values.begin(), values.end(), x);
    if (position == values.end()) {
        std::cout << -1 << std::endl;
    } else {
        std::cout << (position - values.begin()) << std::endl;
    }
    return 0;
}
